def get_field_precision(df, doc=None, currency=None):
	"""get precision based on DocField options and fieldvalue in doc"""
	if df.precision:
		precision = cint(df.precision)

	elif df.fieldtype == "Currency":
		currency_precision = get_currency_precision()
		if currency_precision is not None:
			precision = currency_precision
		else:
			precision = get_precision_from_currency_format(currency or get_field_currency(df, doc))
	else:
		precision = cint(frappe.db.get_default("float_precision")) or 3

	return precision

excerpts.get_field_currency:
def get_field_currency(df, doc=None):
	"""get currency based on DocField options and fieldvalue in doc"""
	currency = None

	if not df.get("options"):
		return None

	if not doc:
		return None

	if not getattr(frappe.local, "field_currency", None):
		frappe.local.field_currency = frappe._dict()

	if not (
		frappe.local.field_currency.get((doc.doctype, doc.name), {}).get(df.fieldname)
		or (
			doc.get("parent")
			and frappe.local.field_currency.get((doc.doctype, doc.parent), {}).get(df.fieldname)
		)
	):
		ref_docname = doc.get("parent") or doc.name

		if ":" in cstr(df.get("options")):
			split_opts = df.get("options").split(":")
			if len(split_opts) == 3 and doc.get(split_opts[1]):
				currency = frappe.get_cached_value(split_opts[0], doc.get(split_opts[1]), split_opts[2])
		else:
			currency = doc.get(df.get("options"))
			if doc.get("parenttype"):
				if currency:
					ref_docname = doc.name
				else:
					if frappe.get_meta(doc.parenttype).has_field(df.get("options")):
						# only get_value if parent has currency field
						currency = frappe.db.get_value(doc.parenttype, doc.parent, df.get("options"))
						if not currency:
							# Parent may not be in DB yet (new document being saved).
							# Use the in-memory parent document reference if available.
							parent = getattr(doc, "parent_doc", None)
							if parent:
								currency = parent.get(df.get("options"))

		if currency:
			frappe.local.field_currency.setdefault((doc.doctype, ref_docname), frappe._dict()).setdefault(
				df.fieldname, currency
			)

	return frappe.local.field_currency.get((doc.doctype, doc.name), {}).get(df.fieldname) or (
		doc.get("parent") and frappe.local.field_currency.get((doc.doctype, doc.parent), {}).get(df.fieldname)
	)

excerpts.precision:
def precision(self, fieldname, parentfield=None) -> int | None:
	"""Return float precision for a particular field (or get global default).

	:param fieldname: Fieldname for which precision is required.
	:param parentfield: If fieldname is in child table."""
	from frappe.model.meta import get_field_precision

	if parentfield and not isinstance(parentfield, str) and parentfield.get("parentfield"):
		parentfield = parentfield.parentfield

	cache_key = parentfield or "main"

	if not hasattr(self, "_precision"):
		self._precision = _dict()

	if cache_key not in self._precision:
		self._precision[cache_key] = _dict()

	if fieldname not in self._precision[cache_key]:
		self._precision[cache_key][fieldname] = None

		doctype = self.meta.get_field(parentfield).options if parentfield else self.doctype
		df = frappe.get_meta(doctype).get_field(fieldname)

		if df and df.fieldtype in ("Currency", "Float", "Percent"):
			self._precision[cache_key][fieldname] = get_field_precision(df, self)

	return self._precision[cache_key][fieldname]

excerpts._fix_numeric_types:
def _fix_numeric_types(self):
	for df in self.meta.get("fields", {"fieldtype": ("in", numeric_fieldtypes)}):
		if df.fieldtype == "Check":
			self.set(df.fieldname, cint(self.get(df.fieldname)))

		elif self.get(df.fieldname) is not None:
			if df.fieldtype == "Int":
				self.set(df.fieldname, cint(self.get(df.fieldname)))

			elif df.fieldtype in ("Float", "Currency", "Percent"):
				self.set(df.fieldname, flt(self.get(df.fieldname)))

	# calling the docstatus property does the job
	self.docstatus

excerpts.cint:
def cint(s: NumericType | str | None, default: int = 0) -> int:
	"""Convert to integer.

	:param s: Number in string or other numeric format.
	:returns: Converted number in python integer type.

	Return default if input cannot be converted to integer.

	Examples:
	>>> cint("100")
	100
	>>> cint("a")
	0
	>>> cint(None)
	0

	"""
	if s is None:
		return default

	try:
		return int(s)
	except Exception:
		try:
			return int(float(s))
		except Exception:
			return default

excerpts.rounded:
def rounded(num, precision=0, rounding_method=None):
	"""Round according to method set in system setting, defaults to banker's rounding"""
	precision = cint(precision)

	rounding_method = (
		rounding_method or frappe.get_system_settings("rounding_method") or "Banker's Rounding (legacy)"
	)

	if rounding_method == "Banker's Rounding":
		return _bankers_rounding(num, precision)
	elif rounding_method == "Banker's Rounding (legacy)":
		return _bankers_rounding_legacy(num, precision)
	elif rounding_method == "Commercial Rounding":
		return _round_away_from_zero(num, precision)
	else:
		frappe.throw(
			frappe._("Unknown Rounding Method: {}").format(rounding_method),
			exc=frappe.InvalidRoundingMethod,
		)

excerpts._bankers_rounding_legacy:
def _bankers_rounding_legacy(num, precision):
	# avoid rounding errors
	multiplier = 10**precision
	num = round(num * multiplier if precision else num, 8)

	floor_num = math.floor(num)
	decimal_part = num - floor_num

	if not precision and decimal_part == 0.5:
		num = floor_num if (floor_num % 2 == 0) else floor_num + 1
	else:
		if decimal_part == 0.5:
			num = floor_num + 1
		else:
			num = round(num)

	return (num / multiplier) if precision else num

excerpts._bankers_rounding:
def _bankers_rounding(num, precision):
	if num == 0:
		return 0.0

	sign = -1 if num < 0 else 1
	multiplier = 10**precision
	num = round(abs(num) * multiplier, 12)

	if num == 0:
		return 0.0

	floor_num = math.floor(num)
	decimal_part = num - floor_num

	epsilon = 2.0 ** (math.log(num, 2) - 52.0)

	if epsilon < 0.5 and abs(decimal_part - 0.5) < epsilon:
		num = floor_num if (floor_num % 2 == 0) else floor_num + 1
	else:
		num = round(num)

	return sign * num / multiplier

excerpts.get_locale_value:
def get_locale_value(key: str, language: str | None = None) -> str | None:
	"""Return the value of the key from the Language record or System Settings.

	:param key: The settings key to get the value for.
	:param language: The language code to get the value for. Defaults to the current user's language.
	"""
	lang = language or frappe.local.lang
	if lang:
		value = frappe.client_cache.get_doc("Language", lang).get(key)

	return value or frappe.db.get_default(key)

